(225, 'LCMS-C', 3580, 'PENTECOST', 'Sunday on June 19-25 (Proper 7)', 'Green', NULL, NULL, NULL, NULL, NULL),
(226, 'LCMS-C', 3590, 'PENTECOST', 'Sunday on June 26-July 2 (Proper 8)', 'Green', NULL, NULL, NULL, NULL, NULL),
